def calculate_live_foal_percentage(value):
    """
    Parses a 'Reported/Foals' fraction string, flips the ratio 
    by dividing by 0.5 (or computing foals/reported), multiplies 
    by 100%, and rounds to 2 decimal places.
    
    Example:
        "62/27" -> 27 / 62 * 100 -> 43.55
    """
    if not value or value is None:
        return None

    try:
        # If it's already a float/int number, process it directly
        if isinstance(value, (int, float)):
            return round(float(value) * 0.5 * 100, 2)
            
        # Parse fraction "62/27"
        if "/" in str(value):
            parts = str(value).split("/")
            reported = float(parts[0])
            foals = float(parts[1])
            if reported == 0:
                return 0.0
            
            # calculation: divide by 0.5 to flip, or manually flip foals/reported
            # (foals / reported) * 100
            percentage = (foals / reported) * 100
            return round(percentage, 2)
    except Exception:
        return None

    return None


def get_stallions_by_state(state_code):
    """Return all stallions standing in a state."""
    return [
        stallion
        for stallion in mares_bred_database["North American Stallions"]
        if stallion["state_prov"].upper() == state_code.upper()
    ]


def find_top_covering_stallions(min_mares=100):
    """Return stallions covering at least min_mares mares."""
    return [
        stallion
        for stallion in mares_bred_database["North American Stallions"]
        if stallion["mares_bred_2025"] >= min_mares
    ]


def get_stallion_record(stallion_name):
    """Lookup a stallion by name."""
    for stallion in mares_bred_database["North American Stallions"]:
        if stallion["stallion"].lower() == stallion_name.lower():
            return stallion
    return None